workflowRefundEstimate=function(studentIndex,classIndex){const student=a.students[studentIndex],c=a.classes[classIndex],orders=a.orders.filter(o=>o.studentId===student?.id&&o.classId===c?.id&&o.paymentState==='已支付'),order=orders.find(o=>o.entitlementState==='已生效'),course=a.courses.find(x=>x.id===c?.courseId),paid=order?money(order.paid):0,total=order?.lessonSnapshot?.length||course?.lessons?.length||0,records=a.attendance.filter(x=>x.classIndex===classIndex&&x.studentIndex===studentIndex&&x.consumptionConfirmed===true),consumed=new Set(records.map(x=>x.sessionId||`${x.date}|${x.session}`)).size,unit=total?paid/total:0;return {student,c,order,paid,total,consumed,unit,refund:total?Math.max(0,Math.round((paid-unit*consumed)*100)/100):0,ready:!!order&&total>0&&consumed<=total}};
const workflowWithdrawBase=flowPage;
flowPage=function(type){if(type!=='withdraw')return workflowWithdrawBase(type);const student=a.students[a.selectedStudent],classes=student?a.classes.map((c,i)=>({...c,index:i})).filter(c=>a.orders.some(o=>o.studentId===student.id&&o.classId===c.id&&o.entitlementState==='已生效')):[];
 if(!classes.some(c=>c.index===workflowState.refundClass))workflowState.refundClass=classes[0]?.index;
 const est=student&&Number.isInteger(workflowState.refundClass)?workflowRefundEstimate(a.selectedStudent,workflowState.refundClass):null;
 return aHeading('学生退课／退班','按实际订单和已确认课消试算；退课与财务退款分开记录')+`<div class="card pad"><button class="btn" onclick="a.modal='selectStudent';academicRender()">${student?'重新选择学生':'选择学生'}</button>${student?`<p>${esc(student.name)}</p><select id="flow-from" class="select" onchange="workflowState.refundClass=Number(this.value);academicRender()">${classes.map(c=>`<option value="${c.index}" ${c.index===workflowState.refundClass?'selected':''}>${esc(c.name)}</option>`).join('')}</select>`:''}${est?`<div class="summary-box"><div class="summary-line"><span>已确认实收</span><strong>¥${est.paid.toFixed(2)}</strong></div><div class="summary-line"><span>已确认课消 / 总讲次</span><strong>${est.consumed} / ${est.total||'未配置'}</strong></div><div class="summary-line"><span>预计可退</span><strong>¥${est.refund.toFixed(2)}</strong></div></div><p class="notice">${est.ready?'按订单实收金额在课程各讲等额分摊，仅扣除明确确认的课消。确认退课后撤销未来点名资格，历史保留；财务到账需另行确认。':'缺少有效已付款订单或课程讲次，不能自动计算退款。请先补齐依据。'}</p><button class="btn primary" ${est.ready?'':'disabled'} onclick="finishFlow('withdraw')">确认退课并提交退款</button>`:'<p class="empty">请选择有有效课程权益的学生。</p>'}</div>`};
const workflowOtherFinish=finishFlow;
finishFlow=function(type){if(type!=='withdraw'){if(type==='tempMove'){toast('请在课表中选择具体课次，再调整本节学生');nav('schedule');return}return workflowOtherFinish(type)}if(!workflowGuard('withdraw'))return;
 const si=a.selectedStudent,ci=workflowState.refundClass,est=workflowRefundEstimate(si,ci);if(!est.ready){toast('退款依据不完整');return}a.refunds=a.refunds||[];if(a.refunds.some(r=>r.orderId===est.order.id)){toast('该订单已提交退课退款');return}
 const now=new Date(),today=[now.getFullYear(),String(now.getMonth()+1).padStart(2,'0'),String(now.getDate()).padStart(2,'0')].join('-'),refund={id:`RF-${Date.now()}`,student:est.student.name,studentId:est.student.id,course:est.c.course,orderId:est.order.id,paid:est.paid,consumed:est.consumed,total:est.total,amount:est.refund,status:'待财务退款',createdAt:now.toISOString()};a.refunds.unshift(refund);est.order.entitlementState='已退课';est.order.refundState='待退款';est.c.studentIds=(est.c.studentIds||[]).filter(id=>id!==est.student.id);est.c.students=Math.max(0,est.c.students-1);if(est.student.className===est.c.name)est.student.className='—';est.student.classIds=(est.student.classIds||[]).filter(id=>id!==est.c.id);
 if(!a.orders.some(o=>o.studentId===est.student.id&&o.entitlementState==='已生效'))est.student.status='历史';
 a.attendance.forEach(x=>{if(x.classIndex===ci&&x.studentIndex===si&&x.date>=today&&!x.consumptionConfirmed&&!['已考勤','已消课'].includes(x.status)){x.previousStatus=x.attendance;x.attendance='退课后撤销';x.status='已撤销';x.refundId=refund.id}});workflowPersist();academicRender();toast(`退课已完成，¥${est.refund.toFixed(2)} 进入待财务退款`)};
