function workflowSaveSessionAttendance(){if(!workflowGuard('academic'))return;const {classIndex}=workflowState.selectedSession,c=a.classes[classIndex],sessionId=workflowSessionKey(c);document.querySelectorAll('.wf-attendance').forEach(el=>{const studentId=el.dataset.student,studentIndex=a.students.findIndex(s=>s.id===studentId),consume=[...document.querySelectorAll('.wf-consume')].find(e=>e.dataset.student===studentId)?.checked;if(el.value==='未考勤'&&consume)return;let x=a.attendance.find(x=>x.sessionId===sessionId&&x.studentId===studentId)||a.attendance.find(x=>x.classIndex===classIndex&&x.studentIndex===studentIndex&&x.date===c.date);if(!x){x={};a.attendance.push(x)}Object.assign(x,{classIndex,studentIndex,studentId,sessionId,date:c.date,time:c.time,session:c.lessonId,status:el.value==='未考勤'?'未考勤':'已考勤',attendance:el.value,consumptionConfirmed:!!consume})});workflowPersist();toast('本节点名与课消已保存')}
function workflowSaveTeachingRecord(){if(!workflowGuard('academic'))return;const c=a.classes[workflowState.selectedSession.classIndex],record=$('#workflow-teaching-note').value.trim();if(!record){toast('请填写授课内容与课堂情况');return}const id=workflowSessionKey(c);c.sessions=c.sessions||[];let row=c.sessions.find(x=>x.sessionId===id&&x.record);if(!row){row={sessionId:id,date:c.date};c.sessions.push(row)}row.record=record;row.updatedAt=new Date().toISOString();workflowPersist();toast('授课记录已保存')}
workflowConfirmSubstitute=function(){if(!workflowGuard('academic'))return;const c=a.classes[workflowState.selectedSession.classIndex],teacher=$('#workflow-substitute')?.value;if(!teacher){toast('请选择代课老师');return}if(a.classes.some(x=>x.id!==c.id&&x.date===c.date&&x.time===c.time&&x.teacher===teacher)){toast('该老师同一时段已有课程，请先处理冲突');return}c.sessions=c.sessions||[];const id=workflowSessionKey(c);let row=c.sessions.find(x=>x.sessionId===id&&x.substitute);if(!row){row={sessionId:id,date:c.date};c.sessions.push(row)}row.substitute=teacher;workflowPersist();workflowOpenSession(workflowState.selectedSession.classIndex);toast('本节代课已更新')};
workflowCommitMove=function(){if(!workflowGuard('academic'))return;const source=a.classes[workflowState.selectedSession.classIndex],studentId=$('#workflow-move-student')?.value,target=a.classes.find(c=>c.id===$('#workflow-move-target')?.value);if(!target||!workflowSessionRoster(source).some(s=>s.id===studentId)){toast('请选择本节学生与目标课次');return}if(target.courseId!==source.courseId||target.lessonId!==source.lessonId||target.lessonVersion!==source.lessonVersion||target.date!==source.date){toast('目标课次的授课内容或版本不一致');return}if(workflowSessionRoster(target).length>=target.capacity){toast('目标班本节已满');return}a.sessionAdjustments=a.sessionAdjustments||[];if(a.sessionAdjustments.some(m=>m.studentId===studentId&&m.sourceClassId===source.id&&m.date===source.date&&m.status==='已确认')){toast('该学生本节已有调班安排');return}a.sessionAdjustments.push({id:`MV-${Date.now()}`,studentId,sourceClassId:source.id,targetClassId:target.id,date:source.date,courseId:source.courseId,lessonId:source.lessonId,lessonVersion:source.lessonVersion,status:'已确认'});a.attendance.forEach(x=>{if(x.classIndex===workflowState.selectedSession.classIndex&&a.students[x.studentIndex]?.id===studentId&&x.date===source.date&&x.status==='未考勤'){x.status='已撤销';x.attendance='本节调出'}});workflowPersist();workflowOpenSession(workflowState.selectedSession.classIndex);toast('本节名单已调整，班级长期归属保留')};
const workflowClassSaveChecked=saveClass;
saveClass=function(){if(!workflowGuard('classes'))return;const old=a.selectedClass===null?null:a.classes[a.selectedClass],capacity=Number($('#class-capacity')?.value);if(!Number.isFinite(capacity)||capacity<Math.max(1,old?.students||0)){toast('班级容量不能少于现有人数且至少为1');return}workflowClassSaveChecked();a.classes.forEach(c=>{const course=a.courses.find(x=>x.id===c.courseId||x.name===c.course);c.lessonId=c.lessonId||course?.lessons?.[0]?.id||`${course?.id}-PENDING-1`;c.studentIds=c.studentIds||[]});workflowPersist()};
const workflowShelfSingle=mallSetShelf,workflowShelfBatch=mallBatchShelf;
mallSetShelf=function(...args){if(!workflowGuard('mallShelf'))return;workflowShelfSingle(...args);workflowPersist()};
mallBatchShelf=function(...args){if(!workflowGuard('mallShelf'))return;workflowShelfBatch(...args);workflowPersist()};
const workflowSwitchIdentity=permissionChangeIdentity;
permissionChangeIdentity=function(id){document.querySelectorAll('#workflow-session-drawer,#workflow-lead-modal,#workflow-product-detail').forEach(x=>x.remove());const box=$('#global-action-results');if(box){box.hidden=true;box.innerHTML=''}workflowSwitchIdentity(id);if(!permissionState.dirty){state.page='home';render();permissionRefreshNavigation()}};
const workflowPolicyChecked=workflowSaveLeadPolicy;
workflowSaveLeadPolicy=function(){if(!workflowGuard('policy'))return;const p=workflowState.leadPolicy;if(![p.reserveDays,p.reclaimDays,p.firstFollowHours].every(v=>Number.isFinite(v)&&v>0)){toast('所有时限必须大于0');return}workflowPolicyChecked();toast('演示策略已保存；自动回收尚未接入定时执行')};
// Keep schedule filters and the student view tied to effective per-session rosters.
schedulePage=function(){const v=workflowState.scheduleView,rows=a.classes.map((c,index)=>({c,index})).filter(({c})=>(!workflowState.from||c.date>=workflowState.from)&&(!workflowState.to||c.date<=workflowState.to)&&(!workflowState.campus||c.campus===workflowState.campus)&&(!workflowState.teacher||c.teacher===workflowState.teacher||(c.sessions||[]).some(s=>s.sessionId===workflowSessionKey(c)&&s.substitute===workflowState.teacher))&&(!workflowState.course||c.course===workflowState.course));
 const select=(key,label,values)=>`<select class="select" onchange="workflowState.${key}=this.value;academicRender()"><option value="">全部${label}</option>${[...new Set(values)].map(x=>`<option value="${esc(x)}" ${workflowState[key]===x?'selected':''}>${esc(x)}</option>`).join('')}</select>`;
 const out=[];rows.forEach(({c,index})=>{const actual=(c.sessions||[]).find(s=>s.sessionId===workflowSessionKey(c)&&s.substitute)?.substitute||c.teacher,roster=workflowSessionRoster(c),people=v==='student'?roster.filter(s=>!workflowState.student||s.id===workflowState.student):[null];people.forEach(s=>out.push(`<tr><td>${esc(c.date)} ${esc(c.time)}</td><td>${esc(s?.name||(v==='teacher'?actual:c.campus))}</td><td>${esc(c.name)}</td><td>${esc(c.course)}</td><td>${esc(actual)}${actual!==c.teacher?'（代课）':''}</td><td>${esc(c.room)}</td><td>${roster.length}</td><td><button class="btn small" onclick="workflowOpenSession(${index},${s?a.students.indexOf(s):'null'})">课次操作</button></td></tr>`))});
 return aHeading('课表','按校区、老师、学生和日期区间查看已排课次')+`<div class="card pad"><div id="schedule-workflow-controls"><div class="filters"><select class="select" onchange="workflowState.scheduleView=this.value;academicRender()">${[['campus','校区课表'],['teacher','老师课表'],['student','学生课表']].map(([k,t])=>`<option value="${k}" ${v===k?'selected':''}>${t}</option>`).join('')}</select>${select('campus','校区',a.classes.map(c=>c.campus))}${select('teacher','老师',a.classes.flatMap(c=>[c.teacher,...(c.sessions||[]).map(x=>x.substitute).filter(Boolean)]))}${select('course','课程',a.classes.map(c=>c.course))}${v==='student'?`<select class="select" onchange="workflowState.student=this.value;academicRender()"><option value="">全部学生</option>${a.students.map(s=>`<option value="${esc(s.id)}" ${workflowState.student===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select>`:''}<input class="input" type="date" aria-label="开始日期" value="${esc(workflowState.from||'')}" onchange="workflowState.from=this.value;academicRender()"><input class="input" type="date" aria-label="结束日期" value="${esc(workflowState.to||'')}" onchange="workflowState.to=this.value;academicRender()"><button class="btn" onclick="['from','to','campus','teacher','course','student'].forEach(k=>workflowState[k]='');academicRender()">清除筛选</button></div><p class="help">${out.length} 条课次记录。原型只显示已录入的排课日期；班级人数统计与本节名单分别显示。</p>${workflowState.from&&workflowState.to&&workflowState.from>workflowState.to?'<p class="notice">开始日期不能晚于结束日期。</p>':aTable(['日期时间','视角对象','班级','课程','实际授课老师','教室','本节名单人数','操作'],out)}</div></div>`};
// Home shortcuts obey the same role grants as navigation.
const workflowHomeChecked=workflowHome;
workflowHome=function(){workflowHomeChecked();permissionRefreshNavigation();if(!workflowMay('lead'))document.querySelector('.home-greeting .btn')?.remove();document.querySelectorAll('.home-quick button').forEach(b=>{const page=(b.getAttribute('onclick')||'').match(/nav\('([^']+)'\)/)?.[1];if(page&&!permissionCanVisit(page))b.remove()});if(permissionState.identity==='sales'){const metrics=document.querySelectorAll('.workflow-metrics .metric');if(metrics[1])metrics[1].hidden=true;if(metrics[2])metrics[2].hidden=true;if(metrics[3])metrics[3].hidden=true}}
if(!mfSharedForm){state.page='home';render()}
function workflowPublishOffer(index){if(!workflowGuard('mallCoupon'))return;const offer=mallState.activities.coupon[index];if(!offer)return;offer.published=true;offer.status='进行中';offer.publishedAt=new Date().toISOString();workflowPersist();mallRender();toast('优惠版本已发布；报名时仍会核验有效期、课程和资格')}
const workflowActivityActions=mallRowActions;
mallRowActions=function(type,index){if(type!=='coupon')return workflowActivityActions(type,index);const x=mallState.activities.coupon[index];return `<div class="mall-actions"><button onclick="mallEdit('coupon',${index})">编辑</button>${x.status==='进行中'?'<span>已开放报价</span>':`<button onclick="workflowPublishOffer(${index})">发布优惠版本</button>`}<button onclick="mallEnd('coupon',${index})">结束</button></div>`};
const workflowEndOffer=mallEnd;
mallEnd=function(type,index){if(!workflowGuard(type==='coupon'?'mallCoupon':type==='group'?'mallGroup':'mallJoint'))return;workflowEndOffer(type,index);workflowPersist()};
// Keep the configured course scope visible on the published offer list.
const workflowScopedActivityPage=mallActivityPage;
mallActivityPage=function(type){let html=workflowScopedActivityPage(type),i=0;if(type==='coupon')html=html.replace(/<td>全部商品<\/td>/g,()=>`<td>${esc(mallState.activities.coupon[i++]?.courseName||'全部课程')}</td>`);return html};
